const { DateTime } = require('luxon');

const ZONA = 'America/Mexico_City';
const APERTURA = 9;
const CIERRE = 21;

const input = $input.first()?.json || {};
const body = input.body || input;

function txt(v) {
  if (v === null || v === undefined) return '';
  const r = String(v).trim();
  const b = r.toLowerCase();
  if (r === '' || r === '[null]' || b === 'null' || b === 'undefined') return '';
  return r;
}

const ahora = DateTime.now().setZone(ZONA);
const hora = ahora.hour + ahora.minute / 60;
const dentro_de_horario = hora >= APERTURA && hora < CIERRE;

// MODO PRUEBA POR WEBHOOK NORMAL.
// Acepta el formato que manda el portal y formatos manuales desde Postman/n8n.
const text =
  txt(body.text) ||
  txt(body.message) ||
  txt(body.input) ||
  txt(body.mensaje) ||
  txt(body.texto) ||
  txt(body.body);

const chat_id =
  txt(body.chat_id) ||
  txt(body.session_key) ||
  txt(body.wa_id) ||
  'portal-test-chat';

const nombre =
  txt(body.nombre) ||
  txt(body.name) ||
  txt(body.actor) ||
  txt(body.usuario) ||
  'Cliente prueba';

const phone_number_id = txt(body.phone_number_id) || 'intec-prueba';

if (!text) {
  return [{ json: { ok: false, tipo_evento: 'descartar', error: 'Webhook de prueba sin texto.' } }];
}

return [{
  json: {
    ok: true,
    modo: 'prueba',
    tipo_evento: 'mensaje',
    chat_id,
    session_key: `${chat_id}_intec`,
    phone_number_id,
    message_id: `test-${Date.now()}`,
    nombre,
    tipo_mensaje: 'text',
    text,
    media_id: '',
    es_media: false,
    es_rancio: false,
    fuente: 'Webhook de prueba',
    dentro_de_horario,
    hora_local: ahora.toFormat('HH:mm'),
    dia_semana: ahora.setLocale('es').toFormat('cccc')
  }
}];

const base = $('Extraer Datos').first().json || {};
const texto = 'Por ahora la prueba del bot INTEC solo acepta mensajes de texto. Escríbeme tu duda y con gusto te ayudo.';
return [{ json: {
  ok: true,
  chat_id: base.chat_id,
  phone_number_id: base.phone_number_id,
  session_key: base.session_key,
  reply: texto,
  final_text: texto,
  escalar: false,
  motivo_escalamiento: ''
}}];

