// Limpia la salida del agente y devuelve un formato que el portal entiende.
const base = $('Extraer Datos').first().json || {};
const raw = $input.first().json || {};

let texto = String(raw.output ?? raw.text ?? raw.reply ?? '').trim();

const MARCA = '[[ESCALAR]]';
const escalar = texto.includes(MARCA);
texto = texto.split(MARCA).join('').trim();

const REGEX_PRECIO = /(\$\s?\d|(\d{3,5})\s?(pesos|mxn))/i;
let motivo = escalar ? 'El agente marco escalamiento' : '';
if (REGEX_PRECIO.test(texto)) {
  texto = base.dentro_de_horario
    ? 'Permíteme confirmar disponibilidad y en un momento un asesor te comparte el costo exacto.'
    : 'Mañana a primera hora un asesor te confirma disponibilidad y el costo exacto.';
  motivo = 'BLOQUEO: el agente intento dar un precio';
}

if (!texto) texto = 'Permíteme un momento, en seguida te atiendo.';
if (texto.length > 4096) texto = texto.slice(0, 4093) + '...';

return [{
  json: {
    ok: true,
    chat_id: base.chat_id,
    phone_number_id: base.phone_number_id,
    session_key: base.session_key,
    reply: texto,
    final_text: texto,
    escalar: escalar || motivo.startsWith('BLOQUEO'),
    motivo_escalamiento: motivo
  }
}];

