const input = $input.first()?.json || {};
const body = input.body || input;
const headers = input.headers || {};
const configuredSecret = String($env.N8N_PORTAL_KEY || '').trim();
const receivedSecret = String(headers['x-portal-key'] || headers['X-Portal-Key'] || '').trim();

if (!configuredSecret) {
  return [{ json: { ok:false, authorized:false, statusCode:500, error:'N8N_PORTAL_KEY no esta configurada en n8n.' } }];
}
if (!receivedSecret || receivedSecret !== configuredSecret) {
  return [{ json: { ok:false, authorized:false, statusCode:401, error:'No autorizado.' } }];
}

const phone_number_id = String(body.phone_number_id || '').trim();
const wa_id = String(body.wa_id || '').trim();
const texto = String(body.texto || '').trim();
const usuario = String(body.usuario || '').trim();

if (!phone_number_id || !wa_id || !texto || !usuario || texto.length > 4096) {
  return [{ json: { ok:false, authorized:false, statusCode:400, error:'Solicitud invalida.' } }];
}

return [{ json: { ok:true, authorized:true, statusCode:200, phone_number_id, wa_id, texto, usuario, session_key: wa_id + '_ma' } }];

// Code Tool (Agents): debe regresar un solo STRING (JSON.stringify).
// SLOTS_INTEC — Universidad INTEC Colima
//
// Horario (PENDIENTE confirmar detalle por dia con Fernando):
// - Lunes a Sabado: 09:00–18:00
// - Domingo: no hay servicio
//
// Duracion de cita: 20 minutos.
// Hasta 2 visitas simultaneas por franja (MAX_PARALLEL = 2).
//
// Reglas de ocupacion:
// - CUALQUIER evento de dia completo bloquea toda la fecha.
// - Un slot solo se considera ocupado cuando ya hay 2 eventos traslapados (MAX_PARALLEL).
// - Los eventos cancelados no bloquean.

const TZ = "America/Mexico_City";
const OFFSET = "-06:00";

function pad2(n) { return String(n).padStart(2, "0"); }
function safeString(v) { return v === undefined || v === null ? "" : String(v).trim(); }
function safeLower(v) { return safeString(v).toLowerCase(); }
function isObject(v) { return v !== null && typeof v === "object" && !Array.isArray(v); }
function hasOwn(obj, key) { return !!obj && Object.prototype.hasOwnProperty.call(obj, key); }
function truthy(v) { if (v === true) return true; const s = safeLower(v); return s === "true" || s === "1" || s === "yes" || s === "si" || s === "sí"; }
function tryParseJSON(v) { if (typeof v !== "string") return v; const s = v.trim(); if (!s) return v; try { return JSON.parse(s); } catch (_) { return v; } }
function deepParse(value, maxDepth = 6) { let current = value; for (let i = 0; i < maxDepth; i++) { const parsed = tryParseJSON(current); if (parsed === current) break; current = parsed; } return current; }
function normalizeText(v) { return safeString(v).toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/\s+/g, " ").trim(); }
function parseISODate(dateStr) { const m = String(dateStr || "").match(/^(\d{4})-(\d{2})-(\d{2})$/); if (!m) return null; return { y: +m[1], mo: +m[2], d: +m[3] }; }
function addDaysISO(dateStr, add) { const p = parseISODate(dateStr); if (!p) return null; const dt = new Date(Date.UTC(p.y, p.mo - 1, p.d)); dt.setUTCDate(dt.getUTCDate() + add); return `${dt.getUTCFullYear()}-${pad2(dt.getUTCMonth() + 1)}-${pad2(dt.getUTCDate())}`; }
function isoDow(dateStr) { const p = parseISODate(dateStr); if (!p) return null; return new Date(Date.UTC(p.y, p.mo - 1, p.d)).getUTCDay(); }
function labelEs(dateStr) { const p = parseISODate(dateStr); if (!p) return ""; const dt = new Date(Date.UTC(p.y, p.mo - 1, p.d, 12, 0, 0)); return dt.toLocaleDateString("es-MX", { weekday: "long", day: "numeric", month: "long", year: "numeric", timeZone: TZ }).replace(",", ""); }
function hmToMin(hm) { const m = String(hm || "").match(/^(\d{1,2}):(\d{2})$/); if (!m) return null; const hh = +m[1]; const mm = +m[2]; if (hh < 0 || hh > 23 || mm < 0 || mm > 59) return null; return hh * 60 + mm; }
function minToHM(min) { return `${pad2(Math.floor(min / 60))}:${pad2(min % 60)}`; }
function buildISO(date, min) { return `${date}T${minToHM(min)}:00${OFFSET}`; }
function fullDayQueryRange(date) {
  const nextDate = addDaysISO(date, 1);
  return {
    after: `${date}T00:00:00${OFFSET}`,
    before: nextDate ? `${nextDate}T00:00:00${OFFSET}` : `${date}T23:59:59${OFFSET}`
  };
}
function overlaps(aS, aE, bS, bE) { return aS < bE && aE > bS; }

const DAY_WORDS = [
  { k: ["domingo"], dow: 0 }, { k: ["lunes"], dow: 1 }, { k: ["martes"], dow: 2 },
  { k: ["miercoles"], dow: 3 }, { k: ["jueves"], dow: 4 }, { k: ["viernes"], dow: 5 }, { k: ["sabado"], dow: 6 }
];

const MESES_MAP = { enero:1, febrero:2, marzo:3, abril:4, mayo:5, junio:6, julio:7, agosto:8, septiembre:9, setiembre:9, octubre:10, noviembre:11, diciembre:12 };

function parseExplicitDateFromText(text, baseDate) {
  const s = normalizeText(text);
  const baseP = parseISODate(baseDate);
  const baseYear = baseP ? baseP.y : new Date().getFullYear();

  // Detectar si hay intención de "después de" / "a partir de" / "posterior a"
  const isAfter = /\b(despues|posterior|a partir|mas adelante|mas tarde)\b/.test(s);

  // Patrón: "23 de junio" o "23 de junio de 2026" o "junio 23"
  let day = null, month = null, year = null;

  const mDayMonth = s.match(/\b(\d{1,2})\s*(?:de\s*)?(enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|setiembre|octubre|noviembre|diciembre)(?:\s*(?:de|del)?\s*(\d{4}))?\b/);
  if (mDayMonth) {
    day = parseInt(mDayMonth[1]);
    month = MESES_MAP[mDayMonth[2]];
    year = mDayMonth[3] ? parseInt(mDayMonth[3]) : baseYear;
  } else {
    // Patrón: "junio 23" (mes primero)
    const mMonthDay = s.match(/\b(enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|setiembre|octubre|noviembre|diciembre)\s*(\d{1,2})\b/);
    if (mMonthDay) {
      month = MESES_MAP[mMonthDay[1]];
      day = parseInt(mMonthDay[2]);
      year = baseYear;
    } else {
      // Patrón: solo número de día ("el 23", "puedo el 23", "para el 23")
      // Solo aplica si NO hay palabra de día de semana ni "mañana"/"hoy" en el texto
      const hasWeekday = DAY_WORDS.some(d => d.k.some(k => s.includes(k)));
      const hasRelative = s.includes("hoy") || s.includes("manana") || s.includes("pasado manana");
      if (!hasWeekday && !hasRelative) {
        const mOnlyDay = s.match(/\b(?:el|para el|puedo el|dia)\s*(\d{1,2})\b(?!\s*(?::|am|pm|hrs|horas))/);
        if (mOnlyDay) {
          day = parseInt(mOnlyDay[1]);
          // Usa el mes/año base; si el día ya pasó este mes, usa el siguiente mes
          month = baseP ? baseP.mo : (new Date()).getMonth() + 1;
          year = baseYear;
        }
      }
    }
  }

  if (day === null || month === null || day < 1 || day > 31 || month < 1 || month > 12) {
    return { date: null, isAfter };
  }

  // Construir fecha candidata
  let candidate = `${year}-${pad2(month)}-${pad2(day)}`;

  // Si la fecha candidata ya pasó respecto a baseDate, y no se especificó año explícito, avanzar al año siguiente
  if (baseDate && candidate < baseDate) {
    const explicitYear = mDayMonth && mDayMonth[3];
    if (!explicitYear) {
      candidate = `${year + 1}-${pad2(month)}-${pad2(day)}`;
    }
  }

  return { date: candidate, isAfter };
}


function findNextWeekday(baseDate, wantDow) { const baseDow = isoDow(baseDate); if (baseDow === null) return null; let add = wantDow - baseDow; if (add < 0) add += 7; return addDaysISO(baseDate, add); }

function parseTimeFromText(text) {
  const s = normalizeText(text);
  const mAmPm = s.match(/(?:^|\s)(\d{1,2})(?::(\d{2}))?\s*(am|pm)(?:\s|$)/);
  if (mAmPm) { let hh = +mAmPm[1]; const mm = mAmPm[2] ? +mAmPm[2] : 0; const ap = mAmPm[3]; if (mm < 0 || mm > 59) return null; if (hh < 1 || hh > 12) return null; if (hh === 12) hh = 0; if (ap === "pm") hh += 12; if (hh < 0 || hh > 23) return null; return `${pad2(hh)}:${pad2(mm)}`; }
  const m24 = s.match(/(?:^|\s)(\d{1,2}):(\d{2})(?:\s|$)/);
  if (m24) { const hh = +m24[1]; const mm = +m24[2]; if (hh < 0 || hh > 23 || mm < 0 || mm > 59) return null; return `${pad2(hh)}:${pad2(mm)}`; }
  return null;
}

function detectTurn(text) {
  const s = normalizeText(text);
  const hasTarde = s.includes("tarde") || s.includes("turno tarde") || s.includes("en la tarde") || s.includes("por la tarde") || s.includes("segundo turno");
  const hasManana = s.includes("manana") || s.includes("matutino") || s.includes("en la manana") || s.includes("por la manana") || s.includes("temprano") || s.includes("primer turno") || s.includes("1er turno") || s.includes("turno de manana");
  if (hasTarde && !hasManana) return "TARDE";
  if (hasManana && !hasTarde) return "MANANA";
  if (hasTarde && hasManana) return "AMBIGUO";
  return "";
}

function windowsForDate(date) {
  const dow = isoDow(date);
  if (dow === null) return [];
  if (dow === 0) return []; // domingo cerrado
  return [{ name: "GENERAL", start: 9 * 60, end: 18 * 60 }];
}

function nextDateWithTurn(baseDate, turn) { let d = baseDate; for (let i = 0; i < 14; i++) { const ws = windowsForDate(d); if (ws.some(x => x.name === turn)) return d; d = addDaysISO(d, 1); if (!d) break; } return null; }
function isDateInAllDayRange(target, startDate, endDateExclusive) { if (!startDate || !endDateExclusive) return false; return target >= startDate && target < endDateExclusive; }
function nextFallbackDate(targetDate) { let d = targetDate; for (let i = 0; i < 14; i++) { d = addDaysISO(d, 1); if (!d) return ""; if (windowsForDate(d).length > 0) return d; } return ""; }

function nextServiceDateOnOrAfter(date) {
  let d = date;
  for (let i = 0; i < 14; i++) {
    if (!d) return "";
    if (windowsForDate(d).length > 0) return d;
    d = addDaysISO(d, 1);
  }
  return "";
}

let payload = {};
try { if (typeof input === "object" && input) { payload = { ...input }; } else if (typeof input === "string" && input.trim()) { const parsedInput = deepParse(input); if (isObject(parsedInput)) { payload = { ...parsedInput }; } else { payload = { input: String(input) }; } } } catch (_) {}
try { if (typeof query === "object" && query) { payload = { ...query, ...payload }; } else if (typeof query === "string" && query.trim()) { const parsedQuery = deepParse(query); if (isObject(parsedQuery)) { payload = { ...parsedQuery, ...payload }; } else if (!payload.input) { payload.input = String(query); } } } catch (_) {}
try { if (payload && typeof payload.query === "string" && payload.query.trim()) { const q = deepParse(payload.query); if (isObject(q)) { payload = { ...payload, ...q }; } else if (!payload.input) { payload.input = String(payload.query); } } else if (payload && isObject(payload.query)) { payload = { ...payload, ...payload.query }; } } catch (_) {}
try { if (payload && typeof payload.response === "string" && payload.response.trim()) { const r = deepParse(payload.response); if (isObject(r)) payload = { ...payload, ...r }; } else if (payload && isObject(payload.response)) { payload = { ...payload, ...payload.response }; } } catch (_) {}
try { if (typeof $json === "object" && $json) { payload = { ...$json, ...payload }; } } catch (_) {}

const text = safeString(payload.input || payload.mensaje || payload.text || payload.message || payload.prompt || payload.userMessage || "");
const normalizedText = normalizeText(text);

// Conserva el día de la semana pedido explícitamente.
// Ejemplo: "para el jueves" bloqueado -> jueves de la siguiente semana.
let requestedWeekdayDow = null;
let requestedWeekdayName = "";

for (const dayWord of DAY_WORDS) {
  if (dayWord.k.some(k => normalizedText.includes(k))) {
    requestedWeekdayDow = dayWord.dow;
    requestedWeekdayName = dayWord.k[0];
    break;
  }
}

// ======================================================
// CONTEXTO DE LA PROPUESTA ANTERIOR
// ======================================================
//
// Primera consulta:
// "¿Tienen citas para el miércoles?"
// Si está bloqueado, se busca la PRIMERA fecha disponible.
//
// Elección posterior:
// El bot ya ofreció lunes 27 y el paciente responde
// "Puede ser para el jueves".
// Se debe buscar jueves 30, nunca volver al jueves 23.

let previousBotMessage = safeString(
  payload.previous_bot_message ||
  payload.previousBotMessage ||
  payload.ultimo_mensaje_bot ||
  ""
);

// Intentar recuperar automáticamente el último mensaje guardado.
try {
  if (!previousBotMessage) {
    previousBotMessage = safeString(
      $("Edit Fields12").item.json.ultimo_mensaje_bot || ""
    );
  }
} catch (_) {}

const nowCdmxISO = safeString(payload.nowCdmxISO || payload.now || "");
const baseDate = /^\d{4}-\d{2}-\d{2}/.test(nowCdmxISO)
  ? nowCdmxISO.slice(0, 10)
  : "";

const normalizedPreviousBot = normalizeText(previousBotMessage);

const previousBotOfferedAvailability =
  (
    normalizedPreviousBot.includes("tengo estos horarios") ||
    normalizedPreviousBot.includes("estos horarios disponibles") ||
    normalizedPreviousBot.includes("para ese dia tengo") ||
    normalizedPreviousBot.includes("cual te acomoda") ||
    normalizedPreviousBot.includes("volver a tener citas") ||
    normalizedPreviousBot.includes("volvera a tener citas") ||
    normalizedPreviousBot.includes("a partir del")
  ) &&
  (
    normalizedPreviousBot.includes("horario") ||
    normalizedPreviousBot.includes("cita") ||
    normalizedPreviousBot.includes("disponibilidad")
  );

const currentLooksLikeDayChoice =
  requestedWeekdayDow !== null &&
  (
    normalizedText.includes("puede ser") ||
    normalizedText.includes("mejor") ||
    normalizedText.includes("prefiero") ||
    normalizedText.includes("entonces") ||
    normalizedText.includes("y para") ||
    normalizedText.includes("que sea") ||
    normalizedText.includes("para el") ||
    normalizedText.includes("para este") ||
    normalizedText.includes("para ese") ||
    normalizedText.split(" ").length <= 6
  );

let notBeforeDate = safeString(
  payload.not_before_date ||
  payload.notBeforeDate ||
  payload.availability_from_date ||
  ""
);

if (!/^\d{4}-\d{2}-\d{2}$/.test(notBeforeDate)) {
  notBeforeDate = "";
}

// Extraer la fecha ofrecida del mensaje anterior.
// Ejemplo: "lunes 27 de julio de 2026".
if (!notBeforeDate && previousBotOfferedAvailability && baseDate) {
  const parsedPreviousOffer = parseExplicitDateFromText(
    previousBotMessage,
    baseDate
  );

  if (parsedPreviousOffer.date) {
    notBeforeDate = parsedPreviousOffer.date;
  }
}

const inferredFollowUpDayChoice =
  previousBotOfferedAvailability &&
  currentLooksLikeDayChoice &&
  !!notBeforeDate;

// false -> primera fecha disponible.
// true  -> conservar el día elegido después de una propuesta.
const preserveRequestedWeekday =
  truthy(payload.preserve_requested_weekday) ||
  truthy(payload.preserveRequestedWeekday) ||
  safeString(payload.fallback_mode).toUpperCase() === "SAME_WEEKDAY" ||
  inferredFollowUpDayChoice;

const explicitDate = safeString(payload.date || "");
let targetDate = "";

// En una elección posterior, la fecha mínima ofrecida manda sobre
// cualquier fecha antigua que el agente haya calculado.
if (
  preserveRequestedWeekday &&
  requestedWeekdayDow !== null &&
  /^\d{4}-\d{2}-\d{2}$/.test(notBeforeDate)
) {
  targetDate = findNextWeekday(notBeforeDate, requestedWeekdayDow) || "";
}

if (!targetDate && /^\d{4}-\d{2}-\d{2}$/.test(explicitDate)) {
  targetDate = explicitDate;
} else if (!targetDate) {
  // PRIORIDAD MÁXIMA: fecha explícita en el texto ("23 de junio", "después del 23", "el 23")
  let _afterConstraintDate = null;
  const _explicitParsed = parseExplicitDateFromText(text, baseDate);
  if (_explicitParsed.date) {
    if (_explicitParsed.isAfter) {
      // "después del 23 de junio" → buscar el día hábil siguiente a esa fecha (no esa fecha misma)
      _afterConstraintDate = addDaysISO(_explicitParsed.date, 1);
      targetDate = _afterConstraintDate;
    } else {
      // Fecha explícita directa ("23 de junio", "el 23")
      targetDate = _explicitParsed.date;
    }
  }

  // "próxima semana", "otra semana", "la que viene", "siguiente semana"
  const _isNextWeek = normalizedText.includes("proxima semana") ||
                      normalizedText.includes("la proxima semana") ||
                      normalizedText.includes("siguiente semana") ||
                      normalizedText.includes("otra semana") ||
                      normalizedText.includes("la otra semana") ||
                      normalizedText.includes("la que viene") ||
                      normalizedText.includes("la proxima");
  if (_isNextWeek) {
    if (baseDate) {
      // Si menciona un día de la semana específico, buscar ese día la PRÓXIMA semana (no esta)
      let _foundDayNextWeek = false;
      for (const _dw of DAY_WORDS) {
        if (_dw.k.some(k => normalizedText.includes(k))) {
          // Saltar a la próxima semana primero, luego buscar ese día
          const _nextMonday = addDaysISO(baseDate, (8 - isoDow(baseDate)) % 7 || 7);
          const _nextWeekStart = _nextMonday;
          let _d = _nextWeekStart;
          for (let _i = 0; _i < 7; _i++) {
            if (isoDow(_d) === _dw.dow) { targetDate = _d; _foundDayNextWeek = true; break; }
            _d = addDaysISO(_d, 1);
          }
          break;
        }
      }
      // Si no especificó día, ir al próximo lunes de la siguiente semana
      if (!_foundDayNextWeek) {
        const baseDow = isoDow(baseDate);
        const add = baseDow <= 1 ? 1 - baseDow : 8 - baseDow;
        targetDate = addDaysISO(baseDate, add);
      }
    }
  }
  if (!targetDate && baseDate) {
    if (normalizedText.includes("pasado manana") || normalizedText.includes("pasadomanana")) { targetDate = addDaysISO(baseDate, 2); }
    else if (normalizedText.includes("hoy")) { targetDate = baseDate; }
