// BÚSQUEDA DETERMINISTA DE LA FECHA DISPONIBLE
// ======================================================
//
// Esta versión no obliga al agente a consultar un día, recibir un fallback
// y volver a comenzar varias veces. La primera consulta al calendario abarca
// hasta 28 días y esta misma tool encuentra la fecha correcta.
//
// Reglas:
//
// 1. Primera consulta del paciente:
//    Si el día solicitado no está disponible, devuelve la PRIMERA fecha libre.
//
// 2. Elección posterior:
//    Si ya se ofreció una fecha y el paciente dice "mejor el jueves",
//    busca ese jueves a partir de la fecha previamente ofrecida.
//
// 3. Devuelve reply_text ya redactado para que el agente no improvise.

const SEARCH_DAYS = 28;

const _hasEventKeyBeforeParsing =
  Object.prototype.hasOwnProperty.call(payload, "events_busy") ||
  Object.prototype.hasOwnProperty.call(payload, "events") ||
  Object.prototype.hasOwnProperty.call(payload, "cal_events");

const requestedDate = targetDate;
const queryAfterISO = buildISO(requestedDate, 0);
const searchEndDate = addDaysISO(requestedDate, SEARCH_DAYS);
const queryBeforeISO = searchEndDate
  ? buildISO(searchEndDate, 0)
  : buildISO(addDaysISO(requestedDate, 14), 0);

if (!_hasEventKeyBeforeParsing) {
  return JSON.stringify({
    ok: true,
    status: "NEEDS_EVENTS",
    needs_events: true,
    date: requestedDate,
    requestedDate,
    label: labelEs(requestedDate),
    queryAfterISO,
    queryBeforeISO,
    searchDays: SEARCH_DAYS,
    preserveRequestedWeekday,
    fallbackMode: preserveRequestedWeekday
      ? "SAME_WEEKDAY_AFTER_PREVIOUS_OFFER"
      : "EARLIEST_AVAILABLE",
    notBeforeDate,
    instruction:
      "Consulta DISPONIBILIDAD_CALENDARIO una sola vez con queryAfterISO/queryBeforeISO y devuelve TODOS los eventos a SLOTS_ESP_DENTALES."
  });
