function looksLikeCalendarEvent(obj) {
  if (!obj || !isObject(obj)) return false;

  return !!(
    obj.summary ||
    obj.start?.dateTime ||
    obj.start?.date ||
    obj.end?.dateTime ||
    obj.end?.date
  );
}

function extractEventsFromAny(value, depth = 0) {
  if (depth > 6 || value === undefined || value === null) return [];

  const v = deepParse(value);

  if (Array.isArray(v)) {
    const flat = [];

    for (const item of v) {
      if (looksLikeCalendarEvent(item)) {
        flat.push(item);
      } else {
        flat.push(...extractEventsFromAny(item, depth + 1));
      }
    }

    return flat;
  }

  if (looksLikeCalendarEvent(v)) return [v];

  if (isObject(v)) {
    const candidateKeys = [
      "events_busy",
      "events",
      "cal_events",
      "items",
      "data",
      "results",
      "response"
    ];

    for (const key of candidateKeys) {
      if (key in v) {
        const found = extractEventsFromAny(v[key], depth + 1);

        if (found.length || Array.isArray(v[key])) {
          return found;
        }
      }
    }
  }

  return [];
}

const rawEventCarrier = hasOwn(payload, "events_busy")
  ? payload.events_busy
  : hasOwn(payload, "events")
    ? payload.events
    : hasOwn(payload, "cal_events")
      ? payload.cal_events
      : [];

const events = extractEventsFromAny(rawEventCarrier).filter(ev => {
  if (!looksLikeCalendarEvent(ev)) return false;
  return safeLower(ev?.status) !== "cancelled";
});

function eventSummaryInfo(ev) {
  const summary = normalizeText(ev?.summary || "");

  const isMealBlock =
    summary.includes("comida") ||
    summary.includes("hora de comida") ||
    summary.includes("almuerzo");

  const isNamedFullDayBlock =
    summary.includes("bloqueo por ausencia") ||
    (
      summary.includes("calendario bloqueado") &&
      !isMealBlock
    );

  return {
    summary,
    isMealBlock,
    isNamedFullDayBlock
  };
}

// Solo los eventos de DIA COMPLETO (all-day) bloquean la fecha entera.
//
// Un evento CON HORA nunca bloquea todo el dia, aunque su titulo diga
// "calendario bloqueado". Se trata como ocupacion normal y solo bloquea
// los slots de 30 min que realmente se traslapan con su horario.
//
// Motivo: los bloques recurrentes con hora (por ejemplo el de las 14:00)
// estaban cancelando dias completos aunque cayeran fuera del horario de
// atencion de ese dia.
function eventBlocksWholeDate(ev, date) {
  const isAllDay = !!(ev?.start?.date && ev?.end?.date);

  if (!isAllDay) return false;

  const startDate = safeString(ev.start.date).slice(0, 10);
  const endDateExclusive = safeString(ev.end.date).slice(0, 10);

  return isDateInAllDayRange(
    date,
    startDate,
    endDateExclusive
  );
}

function busyIntervalsForDate(date) {
  const busy = [];

  for (const ev of events) {
    if (eventBlocksWholeDate(ev, date)) continue;
    if (ev?.start?.date && ev?.end?.date) continue;

    // Los bloques con hora (comida, bloqueos administrativos con horario)
    // se tratan como ocupacion normal: solo tapan su propio intervalo.
    const start = safeString(ev?.start?.dateTime);
    const end = safeString(ev?.end?.dateTime);

    if (!start || !end) continue;

    const startDate = start.slice(0, 10);
    const endDate = end.slice(0, 10);

    if (date < startDate || date > endDate) continue;

    const startMinRaw = hmToMin(start.slice(11, 16));
    const endMinRaw = hmToMin(end.slice(11, 16));

    if (startMinRaw === null || endMinRaw === null) continue;

    let startMin = 0;
    let endMin = 24 * 60;

    if (startDate === date) startMin = startMinRaw;
    if (endDate === date) endMin = endMinRaw;

    // Evento normal del mismo día.
    if (startDate === date && endDate === date) {
      startMin = startMinRaw;
      endMin = endMinRaw;
    }

    busy.push({
      start: startMin,
      end: endMin,
      title: safeString(ev?.summary) || "Evento"
    });
  }

  return busy;
}

function slotsForDate(date) {
  if (events.some(ev => eventBlocksWholeDate(ev, date))) {
    return {
      date,
      blockedWholeDay: true,
      windows: [],
      busy: [],
      slots: []
    };
  }

  let dateWindows = windowsForDate(date);

  if (turn) {
    dateWindows = dateWindows.filter(w => w.name === turn);
  }

  if (dateWindows.length === 0) {
    return {
      date,
      blockedWholeDay: false,
      windows: [],
      busy: [],
      slots: []
    };
  }

  const busy = busyIntervalsForDate(date);
  const generated = [];

  const SLOT_MIN = 20;
  const MAX_PARALLEL = 2;

  for (const w of dateWindows) {
    for (let t = w.start; t + SLOT_MIN <= w.end; t += SLOT_MIN) {
      generated.push({
        hm: minToHM(t),
        startMin: t,
        endMin: t + SLOT_MIN,
        startTime: buildISO(date, t),
        endTime: buildISO(date, t + SLOT_MIN),
        turn: w.name
      });
    }
  }

  const freeSlots = generated.filter(slot => {
    const overlapCount = busy.filter(interval =>
      overlaps(slot.startMin, slot.endMin, interval.start, interval.end)
    ).length;
    return overlapCount < MAX_PARALLEL;
  });

  return {
    date,
    blockedWholeDay: false,
    windows: dateWindows,
    busy,
    slots: freeSlots
  };
