function nextCandidateDate(date, offset) {
  if (preserveRequestedWeekday && requestedWeekdayDow !== null) {
    return addDaysISO(date, offset * 7);
  }

  return addDaysISO(date, offset);
}

let searchStartDate = requestedDate;

// Protección adicional:
// en una respuesta posterior jamás volver a una fecha anterior
// a la que ya fue ofrecida.
if (
  preserveRequestedWeekday &&
  requestedWeekdayDow !== null &&
  /^\d{4}-\d{2}-\d{2}$/.test(notBeforeDate)
) {
