const shiftedDate = foundDate !== requestedDate;
const availableAll = found.slots.map(slot => slot.hm);
const slots_top = availableAll;

function formatTime12(hm) {
  const mins = hmToMin(hm);

  if (mins === null) return hm;

  let hour = Math.floor(mins / 60);
  const minute = mins % 60;
  const suffix = hour >= 12 ? "p.m." : "a.m.";

  hour = hour % 12;
  if (hour === 0) hour = 12;

  return `${hour}:${pad2(minute)} ${suffix}`;
