  ok: true,
  status: "OK",
  requestedDate,
  requestedLabel: labelEs(requestedDate),
  date: foundDate,
  label: labelEs(foundDate),
  dateShifted: shiftedDate,
  preserveRequestedWeekday,
  fallbackMode: preserveRequestedWeekday
    ? "SAME_WEEKDAY_AFTER_PREVIOUS_OFFER"
    : "EARLIEST_AVAILABLE",
  notBeforeDate,
  previousOfferDetected: previousBotOfferedAvailability,
  followUpDayChoiceDetected: inferredFollowUpDayChoice,
  queryAfterISO,
  queryBeforeISO,
  calendarEventsCount: events.length,
  checkedDates,
  windows: found.windows.map(w => ({
    name: w.name,
    start: minToHM(w.start),
    end: minToHM(w.end)
  })),
  busyIntervals: found.busy.map(interval => ({
    start: minToHM(interval.start),
    end: interval.end >= 24 * 60
      ? "24:00"
